  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center, borderline south={4pt}{0pt}{primary!35},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{90}\selectfont\bfseries\color{secondary} >90\%}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{textdark} GPT-4 USMLE Score}\vspace{12pt}%
    }}
  \end{minipage}\hfill
