    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{90}\selectfont\bfseries\color{primary} 500+}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{textdark} PubMed Articles (2023)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
