% ══ COLUMN 1 ══
\posterbox[darkcard, title={What Are LLMs \& Why Medicine?}]
{name=overview, column=1, between=row5 and row10}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}
    \item \textbf{Rapid Emergence:} Foundation models (GPT-4, Med-PaLM 2) are entering healthcare at unprecedented speed.
    \item \textbf{Broad Impact:} Poised to reshape clinical practice, biomedical research, and medical education.
    \item \textbf{Vast Knowledge:} Models encode enormous scale of medical text data, enabling complex reasoning tasks.
  \end{itemize}\vspace{24pt}

  \centering
  \colorbox{primary!15}{\parbox{0.94\linewidth}{
    \centering\vspace{16pt}
    The pace of adoption has been extraordinary: literature volume exploded in 2023.
    \vspace{16pt}
  }}
}

\posterbox[redcard, title={Risks, Limitations \& Ethical Concerns}]
{name=risks, column=1, between=row10 and row18}{
  \fontsize{34}{44}\selectfont
  Despite impressive benchmarks, significant concerns persist:
  \vspace{16pt}
  \begin{enumerate}
    \item \textbf{Hallucinations:} Fabrication of plausible but incorrect medical information (up to 30\% in QA tasks).
    \item \textbf{Bias \& Equity:} Models amplify training data disparities, risking unequal care recommendations.
    \item \textbf{Privacy:} Patient data transmission raises serious HIPAA and GDPR compliance issues.
    \item \textbf{Clinical Validation:} Evaluations rely heavily on multiple-choice tests, not prospective trials.
    \item \textbf{Over-reliance Risk:} Clinicians may develop automation bias, accepting outputs without appraisal.
  \end{enumerate}\vspace{24pt}

  \centering
  \colorbox{accent!15}{\parbox{0.94\linewidth}{
    \centering\vspace{16pt}
    \textbf{The Tension:} The gap between benchmark excellence (>90\%) and real-world safety (30\% error) demands immediate attention.
    \vspace{16pt}
  }}
}

