    \rowcolor{secondary!15}
    \textbf{Application} & \textbf{Example Use Cases} & \textbf{Maturity} \\
    \hline
    Clinical Docs & Auto-notes, discharge summaries & Pilot \\
    \rowcolor{secondary!05}
    Patient Comm & Q\&A, simplifying jargon & Early \\
    \hline
    Medical Edu & Exam prep, case tutoring & Active \\
    \rowcolor{secondary!05}
    Diagnostics & Radiology interpretation & Research \\
    \hline
    Biomed Research & Literature synthesis & Emerging \\
    \hline
  \end{tabular}
  \vspace{24pt}

  \centering
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{
    \centering\vspace{16pt}
    \textbf{Adoption Trend:} Clinical documentation and patient-facing communication are seeing the fastest integration into electronic health records (EHRs).
    \vspace{16pt}
  }}
}

\posterbox[darkcard, title={Performance Benchmarks}]
{name=performance, column=2, between=row13 and bottom}{
