  \vspace{24pt}
  \begin{itemize}
    \item \textbf{GPT-4:} Exceeded the passing threshold on all three USMLE steps.
    \item \textbf{Med-PaLM 2:} Approaching expert physician-level performance.
    \item \textbf{Earlier Models (GPT-3.5):} Scored near the passing threshold (~60\%) but failed complex clinical reasoning.
  \end{itemize}\vspace{24pt}

  \centering
  \begin{tikzpicture}[x=6mm, y=18mm]
    % Axes
    \draw[thick, textgray] (0,0) -- (10,0);
    \draw[thick, textgray] (0,0) -- (0,3.5);

    % X-axis labels
    \foreach \x in {0, 2, 4, 6, 8, 10} {
      \draw (\x, 0.1) -- (\x, -0.1);
      \node[below, font=\fontsize{28}{34}\selectfont, textgray] at (\x, -0.2) {\x 0\%};
    }

    % Passing Line
    \draw[dashed, accent, very thick] (6, 0) -- (6, 3.5);
    \node[above, font=\fontsize{26}{32}\selectfont\bfseries, accent] at (6, 3.5) {Passing (~60\%)};

    % Bars
    % GPT-3.5
    \fill[primary!30] (0, 0.5) rectangle (6, 1.0);
    \node[right, font=\fontsize{30}{36}\selectfont\bfseries] at (6.1, 0.75) {GPT-3.5 (60\%)};

    % Med-PaLM 2
    \fill[secondary!60] (0, 1.5) rectangle (8.65, 2.0);
    \node[right, font=\fontsize{30}{36}\selectfont\bfseries] at (8.75, 1.75) {Med-PaLM 2 (86.5\%)};

    % GPT-4
    \fill[primary!80] (0, 2.5) rectangle (9.2, 3.0);
    \node[right, font=\fontsize{30}{36}\selectfont\bfseries] at (9.3, 2.75) {GPT-4 (>90\%)};
  \end{tikzpicture}\vspace{12pt}
